// Drift gate for the generated Worker bundle apps/worker/src/ingress/hekimler-automation-ready.{json,ts}.
// The canonical truth is the Hekimler registry; the bundle is regenerated by the owner generator, never hand-edited:
//   cd adapters/hekimler-radar && python -c "from radar.hekimler_continuous_runner import write_worker_profile_bundle as w; w()"
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, mkdtempSync, rmSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const adapter = join(root, 'adapters', 'hekimler-radar');
const committed = join(root, 'apps', 'worker', 'src', 'ingress', 'hekimler-automation-ready.json');

test('committed Hekimler worker bundle equals a fresh regeneration from the canonical registry', (t) => {
  if (spawnSync('python', ['--version']).status !== 0) return t.skip('python not available');
  const tmp = mkdtempSync(join(tmpdir(), 'hek-bundle-'));
  try {
    const dest = join(tmp, 'hekimler-automation-ready.ts');
    const code = `import sys; from pathlib import Path; from radar.hekimler_continuous_runner import write_worker_profile_bundle as w; w(Path(sys.argv[1]))`;
    const out = spawnSync('python', ['-c', code, dest], { cwd: adapter, encoding: 'utf8' });
    assert.equal(out.status, 0, out.stderr);
    const fresh = JSON.parse(readFileSync(join(tmp, 'hekimler-automation-ready.json'), 'utf8'));
    const cur = JSON.parse(readFileSync(committed, 'utf8'));
    const regen = 'regenerate: cd adapters/hekimler-radar && python -c "from radar.hekimler_continuous_runner import write_worker_profile_bundle as w; w()"';
    assert.deepEqual(cur.python_runner_source_ids, fresh.python_runner_source_ids, `python_runner_source_ids drift; ${regen}`);
    assert.deepEqual(cur.profiles, fresh.profiles, `profiles drift; ${regen}`);
  } finally {
    rmSync(tmp, { recursive: true, force: true });
  }
});
